{
  "items": [
    {
      "name": "Real.dist_le_of_mem_Icc",
      "module_name": "Mathlib.Topology.MetricSpace.Pseudo.Real",
      "kind": "theorem",
      "type": "∀ {x y x' y' : ℝ}, x ∈ Set.Icc x' y' → y ∈ Set.Icc x' y' → dist x y ≤ y' - x'"
    },
    {
      "name": "abs_sub_le_of_le_of_le",
      "module_name": "Mathlib.Algebra.Order.Group.Abs",
      "kind": "theorem",
      "type": "∀ {G : Type u_1} [inst : AddCommGroup G] [inst_1 : LinearOrder G] [IsOrderedAddMonoid G] {a b lb ub : G},\n  lb ≤ a → a ≤ ub → lb ≤ b → b ≤ ub → |a - b| ≤ ub - lb"
    },
    {
      "name": "Set.abs_sub_left_of_mem_uIcc",
      "module_name": "Mathlib.Algebra.Order.Group.Pointwise.Interval",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : AddCommGroup α] [inst_1 : LinearOrder α] [IsOrderedAddMonoid α] {a b c : α},\n  c ∈ Set.uIcc a b → |c - a| ≤ |b - a|"
    },
    {
      "name": "Real.dist_le_of_mem_uIcc",
      "module_name": "Mathlib.Topology.MetricSpace.Pseudo.Real",
      "kind": "theorem",
      "type": "∀ {x y x' y' : ℝ}, x ∈ Set.uIcc x' y' → y ∈ Set.uIcc x' y' → dist x y ≤ dist x' y'"
    },
    {
      "name": "Real.dist_le_of_mem_Icc_01",
      "module_name": "Mathlib.Topology.MetricSpace.Pseudo.Real",
      "kind": "theorem",
      "type": "∀ {x y : ℝ}, x ∈ Set.Icc 0 1 → y ∈ Set.Icc 0 1 → dist x y ≤ 1"
    },
    {
      "name": "Set.abs_sub_right_of_mem_uIcc",
      "module_name": "Mathlib.Algebra.Order.Group.Pointwise.Interval",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : AddCommGroup α] [inst_1 : LinearOrder α] [IsOrderedAddMonoid α] {a b c : α},\n  c ∈ Set.uIcc a b → |b - c| ≤ |b - a|"
    }
  ]
}
